mapper.select:
SELECT DISTINCT T.DOMAIN_ID , T.COMPANY_CD , T.TASK_ID , T.TASK_NM , T.TASK_DETAIL , SF_GET_CODE_NM('ko-KR', 'CM001', T.TASK_STATE_CD, T.COMPANY_CD, T.DOMAIN_ID) AS TASK_STATE , T.TASK_START_DT , T.TASK_END_DT , SF_GET_CODE_NM('ko-KR', 'CM002', T.TASK_IMPORTANCE_CD, T.COMPANY_CD, T.DOMAIN_ID) AS TASK_IMPORTANCE , T.TASK_OWNER_MEMBER_ID , T.TASK_PROGRESS , T.CHILD_TASK_ADD_YN , C.COMPANY_NM EMP_COMPANY_NM , E.EMP_NM , T.PARENT_TASK_ID , T.TASK_TYPE_CD , SF_GET_CODE_NM('ko-KR', 'CM007', T.TASK_TYPE_CD, T.COMPANY_CD, T.DOMAIN_ID) AS TASK_TYPE_NM FROM TASK_MASTER T LEFT JOIN EMP_MASTER E ON (E.EMAIL = T.TASK_OWNER_MEMBER_ID AND E.DOMAIN_ID = T.DOMAIN_ID AND E.COMPANY_CD = T.COMPANY_CD) INNER JOIN COMPANY_MASTER C ON (C.DOMAIN_ID = E.DOMAIN_ID AND C.COMPANY_CD = E.COMPANY_CD) INNER JOIN TASK_EMP TE2 ON (TE2.TASK_ID = T.TASK_ID AND TE2.DOMAIN_ID = T.DOMAIN_ID) INNER JOIN EMP_MASTER E2 ON (TE2.EMAIL = E2.EMAIL AND E2.DOMAIN_ID = TE2.DOMAIN_ID AND E2.COMPANY_CD = TE2.COMPANY_CD)
T.DOMAIN_ID = #{domainId} AND (T.DEL_YN = 'N' OR T.DEL_YN IS NULL)
AND T.TASK_STATE_CD = #{taskState}
AND E2.EMP_NM LIKE REPLACE(CONCAT('%', #{taskEmpNm}, '%'), ' ','')
AND T.TASK_NM LIKE REPLACE(CONCAT('%', #{taskNm}, '%'), ' ','')
AND E.EMP_NM LIKE REPLACE(CONCAT('%', #{empNm}, '%'), ' ','')
AND T.TASK_START_DT >= #{taskStartDt}
AND T.TASK_END_DT <= #{taskEndDt}
AND T.TASK_ID NOT IN ( SELECT T.TASK_ID FROM TASK_MASTER T LEFT JOIN EMP_MASTER E ON (E.EMAIL = T.TASK_OWNER_MEMBER_ID AND E.DOMAIN_ID = T.DOMAIN_ID AND E.COMPANY_CD = T.COMPANY_CD) WHERE T.DOMAIN_ID = #{domainId} AND (T.DEL_YN = 'N' OR T.DEL_YN IS NULL) AND T.PARENT_TASK_ID IN ( SELECT T.TASK_ID FROM TASK_MASTER T LEFT JOIN EMP_MASTER E ON (E.EMAIL = T.TASK_OWNER_MEMBER_ID AND E.DOMAIN_ID = T.DOMAIN_ID AND E.COMPANY_CD = T.COMPANY_CD) INNER JOIN TASK_EMP TE2 ON (TE2.TASK_ID = T.TASK_ID AND TE2.DOMAIN_ID = T.DOMAIN_ID) INNER JOIN EMP_MASTER E2 ON (TE2.EMAIL = E2.EMAIL AND E2.DOMAIN_ID = TE2.DOMAIN_ID AND E2.COMPANY_CD = TE2.COMPANY_CD) WHERE T.DOMAIN_ID = #{domainId} AND (T.DEL_YN = 'N' OR T.DEL_YN IS NULL)
AND T.TASK_STATE_CD = #{taskState}
AND E2.EMP_NM LIKE REPLACE(CONCAT('%', #{taskEmpNm}, '%'), ' ','')
AND T.TASK_NM LIKE REPLACE(CONCAT('%', #{taskNm}, '%'), ' ','')
AND E.EMP_NM LIKE REPLACE(CONCAT('%', #{empNm}, '%'), ' ','')
AND T.TASK_START_DT >= #{taskStartDt}
AND T.TASK_END_DT <= #{taskEndDt}
) )
ORDER BY T.TASK_STATE_CD, CASE WHEN T.TASK_END_DT is NULL THEN '2' WHEN T.TASK_END_DT = '' THEN '1' ELSE '0' END, T.TASK_END_DT, T.TASK_IMPORTANCE_CD, COALESCE(T.PARENT_TASK_ID, T.TASK_ID), T.PARENT_TASK_ID IS NOT NULL, T.TASK_ID
LIMIT #{start}, #{length}

SELECT COUNT(DISTINCT T.TASK_ID) FROM TASK_MASTER T LEFT JOIN EMP_MASTER E ON (E.EMAIL = T.TASK_OWNER_MEMBER_ID AND E.DOMAIN_ID = T.DOMAIN_ID AND E.COMPANY_CD = T.COMPANY_CD) INNER JOIN COMPANY_MASTER C ON (C.DOMAIN_ID = E.DOMAIN_ID AND C.COMPANY_CD = E.COMPANY_CD) INNER JOIN TASK_EMP TE2 ON (TE2.TASK_ID = T.TASK_ID AND TE2.DOMAIN_ID = T.DOMAIN_ID) INNER JOIN EMP_MASTER E2 ON (TE2.EMAIL = E2.EMAIL AND E2.DOMAIN_ID = TE2.DOMAIN_ID AND E2.COMPANY_CD = TE2.COMPANY_CD)
T.DOMAIN_ID = #{domainId} AND (T.DEL_YN = 'N' OR T.DEL_YN IS NULL)
AND T.TASK_STATE_CD = #{taskState}
AND E2.EMP_NM LIKE REPLACE(CONCAT('%', #{taskEmpNm}, '%'), ' ','')
AND T.TASK_NM LIKE REPLACE(CONCAT('%', #{taskNm}, '%'), ' ','')
AND E.EMP_NM LIKE REPLACE(CONCAT('%', #{empNm}, '%'), ' ','')
AND T.TASK_START_DT >= #{taskStartDt}
AND T.TASK_END_DT <= #{taskEndDt}
AND T.TASK_ID NOT IN ( SELECT T.TASK_ID FROM TASK_MASTER T LEFT JOIN EMP_MASTER E ON (E.EMAIL = T.TASK_OWNER_MEMBER_ID AND E.DOMAIN_ID = T.DOMAIN_ID AND E.COMPANY_CD = T.COMPANY_CD) WHERE T.DOMAIN_ID = #{domainId} AND (T.DEL_YN = 'N' OR T.DEL_YN IS NULL) AND T.PARENT_TASK_ID IN ( SELECT T.TASK_ID FROM TASK_MASTER T LEFT JOIN EMP_MASTER E ON (E.EMAIL = T.TASK_OWNER_MEMBER_ID AND E.DOMAIN_ID = T.DOMAIN_ID AND E.COMPANY_CD = T.COMPANY_CD) INNER JOIN TASK_EMP TE2 ON (TE2.TASK_ID = T.TASK_ID AND TE2.DOMAIN_ID = T.DOMAIN_ID) INNER JOIN EMP_MASTER E2 ON (TE2.EMAIL = E2.EMAIL AND E2.DOMAIN_ID = TE2.DOMAIN_ID AND E2.COMPANY_CD = TE2.COMPANY_CD) WHERE T.DOMAIN_ID = #{domainId} AND (T.DEL_YN = 'N' OR T.DEL_YN IS NULL)
AND T.TASK_STATE_CD = #{taskState}
AND E2.EMP_NM LIKE REPLACE(CONCAT('%', #{taskEmpNm}, '%'), ' ','')
AND T.TASK_NM LIKE REPLACE(CONCAT('%', #{taskNm}, '%'), ' ','')
AND E.EMP_NM LIKE REPLACE(CONCAT('%', #{empNm}, '%'), ' ','')
AND T.TASK_START_DT >= #{taskStartDt}
AND T.TASK_END_DT <= #{taskEndDt}
) )
